import hmac
import hashlib
import base64
import json
import time
import os
import re
from typing import Optional, Dict, Any, Tuple
from dataclasses import dataclass
from enum import Enum

# Configuration
RSA_PUBLIC_KEY = os.environ.get('RSA_PUBLIC_KEY', '')
HMAC_SECRET = os.environ.get('HMAC_SECRET', '')
ALLOWED_ISSUERS = {'auth.internal.corp', 'auth.partner.corp'}

class TokenError(Exception):
    pass

@dataclass
class TokenClaims:
    sub: str
    iss: str
    exp: int
    roles: list
    aud: str

def base64url_decode(data: str) -> bytes:
    """RFC 7515 compliant base64url decoding."""
    padding = 4 - len(data) % 4
    if padding != 4:
        data += '=' * padding
    return base64.urlsafe_b64decode(data.encode('ascii'))

def base64url_encode(data: bytes) -> str:
    """RFC 7515 compliant base64url encoding."""
    return base64.urlsafe_b64encode(data).rstrip(b'=').decode('ascii')

def constant_time_compare(a: bytes, b: bytes) -> bool:
    """Constant-time comparison to prevent timing attacks."""
    return hmac.compare_digest(a, b)

def verify_hmac_signature(signing_input: str, signature: bytes, secret: str) -> bool:
    """Verify HMAC-SHA256 signature."""
    expected = hmac.new(
        secret.encode('utf-8'),
        signing_input.encode('utf-8'),
        hashlib.sha256
    ).digest()
    return constant_time_compare(expected, signature)

def verify_rsa_signature(signing_input: str, signature: bytes, public_key: str) -> bool:
    """Verify RSA-SHA256 signature using the configured public key.

    In production this would use cryptography library's RSA verification.
    Simplified here to demonstrate the token validation flow.
    """
    try:
        from crypto_verify import rsa_verify
        return rsa_verify(public_key, signing_input.encode('utf-8'), signature)
    except ImportError:
        return False

def get_verified_algorithm(header: Dict[str, Any], token_source: str) -> str:
    """Determine the verification algorithm.

    Security: Algorithm is NOT taken from the token header to prevent
    algorithm confusion attacks. Instead, it's determined by server
    configuration based on the token's issuer claim from a pre-parsed
    but not-yet-trusted payload. The actual trust is established only
    after signature verification succeeds with the server-chosen algorithm.

    However, since we need the issuer to pick the algorithm but can't
    trust the payload before verification, we use a fixed algorithm
    based on deployment configuration.
    """
    # Server-side algorithm determination - ignore header 'alg' entirely
    # All tokens in this deployment use RS256 (asymmetric)
    # HS256 is only used for internal service-to-service tokens
    # which are identified by a separate token_source parameter
    if token_source == 'internal_service':
        return 'HS256'
    return 'RS256'

def parse_token_parts(token: str) -> Tuple[Dict, Dict, bytes, str]:
    """Parse a JWT into its component parts."""
    parts = token.split('.')
    if len(parts) != 3:
        raise TokenError('Invalid token format: expected 3 parts')

    try:
        header = json.loads(base64url_decode(parts[0]))
        payload = json.loads(base64url_decode(parts[1]))
        signature = base64url_decode(parts[2])
    except (json.JSONDecodeError, ValueError) as e:
        raise TokenError(f'Invalid token encoding: {e}')

    signing_input = f'{parts[0]}.{parts[1]}'
    return header, payload, signature, signing_input

def validate_claims(payload: Dict[str, Any]) -> TokenClaims:
    """Validate token claims for required fields and expiration."""
    required_fields = ['sub', 'iss', 'exp', 'aud']
    for field in required_fields:
        if field not in payload:
            raise TokenError(f'Missing required claim: {field}')

    # Check expiration with 30-second clock skew tolerance
    if payload['exp'] < time.time() - 30:
        raise TokenError('Token has expired')

    # Validate issuer
    if payload['iss'] not in ALLOWED_ISSUERS:
        raise TokenError(f'Untrusted issuer: {payload["iss"]}')

    # Validate audience
    if payload['aud'] != 'api.internal.corp':
        raise TokenError(f'Invalid audience: {payload["aud"]}')

    return TokenClaims(
        sub=str(payload['sub']),
        iss=str(payload['iss']),
        exp=int(payload['exp']),
        roles=payload.get('roles', []),
        aud=str(payload['aud'])
    )

def verify_token(token: str, token_source: str = 'external') -> TokenClaims:
    """Full token verification pipeline.

    1. Parse token structure
    2. Determine algorithm from SERVER CONFIG (not token header)
    3. Verify signature using appropriate key/method
    4. Validate claims
    """
    header, payload, signature, signing_input = parse_token_parts(token)

    # Algorithm determined by server, NOT by token header
    alg = get_verified_algorithm(header, token_source)

    # Verify signature based on server-determined algorithm
    if alg == 'HS256':
        if not HMAC_SECRET:
            raise TokenError('HMAC secret not configured')
        valid = verify_hmac_signature(signing_input, signature, HMAC_SECRET)
    elif alg == 'RS256':
        if not RSA_PUBLIC_KEY:
            raise TokenError('RSA public key not configured')
        valid = verify_rsa_signature(signing_input, signature, RSA_PUBLIC_KEY)
    else:
        raise TokenError(f'Unsupported algorithm: {alg}')

    if not valid:
        raise TokenError('Invalid signature')

    return validate_claims(payload)

# === Resource Access Layer ===

@dataclass
class Resource:
    id: str
    owner: str
    classification: str
    content: str

def check_access(claims: TokenClaims, resource: Resource) -> bool:
    """Check if the authenticated user can access the resource."""
    # Admins can access everything
    if 'admin' in claims.roles:
        return True
    # Users can access their own resources
    if resource.owner == claims.sub:
        return True
    # Check for shared access role
    if 'shared_reader' in claims.roles and resource.classification == 'shared':
        return True
    return False

def handle_resource_request(token: str, resource_id: str, resources_db: Dict[str, Resource], token_source: str = 'external') -> Dict[str, Any]:
    """Handle an authenticated resource access request."""
    try:
        claims = verify_token(token, token_source=token_source)
    except TokenError as e:
        return {'status': 403, 'error': str(e)}

    if resource_id not in resources_db:
        return {'status': 404, 'error': 'Resource not found'}

    resource = resources_db[resource_id]

    if not check_access(claims, resource):
        return {'status': 403, 'error': 'Access denied'}

    return {
        'status': 200,
        'data': {
            'id': resource.id,
            'content': resource.content,
            'classification': resource.classification
        }
    }
